import json, os, glob
from datetime import datetime

SESS = r"D:\repository\skills\dsh\langgraph-orchestrator\.sessions"
rows = []
for p in glob.glob(os.path.join(SESS, "*.costs.jsonl")):
    with open(p, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                r = json.loads(line)
            except json.JSONDecodeError:
                continue
            if r.get("role") == "execute" and r.get("tool") == "code_edit_with_signal":
                rows.append((r.get("ts"), r.get("model"), r.get("ok"), r.get("elapsed")))

print("code_edit_with_signal execute rows:", len(rows))
for ts, model, ok, el in sorted(rows):
    when = datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S") if ts else "?"
    print("  %s  model=%-28s ok=%s elapsed=%s" % (when, model, ok, el))

# 同时看 code_editor 的时间分布，判断是不是也偏新
ce = []
for p in glob.glob(os.path.join(SESS, "*.costs.jsonl")):
    with open(p, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                r = json.loads(line)
            except json.JSONDecodeError:
                continue
            if r.get("role") == "execute" and r.get("tool") == "code_editor":
                ce.append(r.get("ts"))
print("\ncode_editor execute rows:", len(ce))
for ts in sorted(ce):
    print("  ", datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M") if ts else "?")

